#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    /* Argument count check */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    /* Parse arguments with strict validation */
    char *end1, *end2;
    long long a = strtoll(argv[1], &end1, 10);
    long long b = strtoll(argv[2], &end2, 10);

    if (end1 == argv[1] || *end1 != '\0' ||
        end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Detect overflow that would occur when negating LLONG_MIN */
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    /* Work with absolute values */
    long long abs_a = (a < 0) ? -a : a;
    long long abs_b = (b < 0) ? -b : b;

    /* Range check (limit is 1,000,000) */
    if (abs_a > 1000000LL || abs_b > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Special case: both numbers are zero */
    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    /* Euclidean algorithm for GCD */
    long long x = abs_a;
    long long y = abs_b;
    while (y != 0) {
        long long r = x % y;
        x = y;
        y = r;
    }
    long long gcd = x; // GCD

    /* Compute LCM using (|a|/gcd)*|b| */
    long long lcm = (abs_a / gcd) * abs_b;

    printf("gcd=%lld lcm=%lld\n", gcd, lcm);
    return 0;
}
